#!/usr/bin/env python3
"""Apply the final v5.4.3 corrections after the one-shot bootstrap patch."""
from __future__ import annotations
import base64
import gzip
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = """"""
patch = gzip.decompress(base64.b64decode(PAYLOAD))
subprocess.run(["git", "apply", "-p1", "--check", "-"], cwd=ROOT, input=patch, check=True)
subprocess.run(["git", "apply", "-p1", "--whitespace=nowarn", "-"], cwd=ROOT, input=patch, check=True)
page = (ROOT / "app" / "page.tsx").read_text(encoding="utf-8")
assert 'operationalRegionalPrevious' in page
assert 'egpu: 98.01741119654318' in page
print("v5.4.3 final regional-dynamics corrections applied")
